import os
import re

def load_grids():
    """Load all grids from session - demos, test input, and any others"""
    try:
        d = os.environ['RLM_SESSION_DIR']
        sessions_file = os.path.join(d, '../../sessions/') + os.path.basename(d) + '.jsonl'
        full_path = os.path.normpath(sessions_file)

        if os.path.exists(full_path):
            t = open(full_path, 'r').read()
            demos = {}
            for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
                k, h, w = m[1], int(m[2]), int(m[3])
                # Get the next h lines
                lines = []
                for i in range(h):
                    line_end = t.find('\n', m.end() + i + 1)
                    if line_end == -1:
                        line_end += 1
                    lines.append(t[m.end()-1+1]:line_end])  # Actually let's just slice differently
                break

            # Let's try simpler approach
            lines = t.split('\n')
            current_text = t[m.end():]
            lines = current_text.split('\n')[:h]
            grid = [[int(x) for x in line] if line.strip() else [] for line in lines]
            demos[k] = grid
            print(f"Loaded {k}: {h}x{w}")
            print(grid[0][:5])[:]
            return demos
        else:
            print(f"No session file at {full_path}")
            return {}
    except Exception as e:
        print(f"Error loading grids: {e}")
        return {}

demos = load_grids()
print(f"Available demos: {list(demos.keys())}")

